import{_ as e,o as a,c as s,ag as i}from"./chunks/framework.2cFhd8Ux.js";const u=JSON.parse('{"title":"Week 0 — Before the First Seminar","description":"","frontmatter":{"source":"setup/README.md"},"headers":[],"relativePath":"setup/index.md","filePath":"setup/index.md"}'),n={name:"setup/index.md"};function o(r,t,h,l,d,p){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="week-0--before-the-first-seminar" tabindex="-1">Week 0 — Before the First Seminar <a class="header-anchor" href="#week-0--before-the-first-seminar" aria-label="Permalink to &quot;Week 0 — Before the First Seminar&quot;">​</a></h1><blockquote><p>About 90 minutes of setup, so that week 1 starts with running and extending an agent, not signing up for things.</p></blockquote><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before the first Seminar</strong></td><td>About 90 minutes: accounts and the Student Developer Pack application, the data settings, one free LLM API key, a test Codespace, and a first read of the agent safety contract</td></tr><tr><td><strong>During week 1</strong></td><td>Sign the <a href="./safety-contract.html">agent safety contract</a> on Canvas; follow up on GitHub Education if it hasn&#39;t been approved</td></tr><tr><td><strong>You need</strong></td><td>A laptop with a modern browser, your phone (for two-factor authentication), and your UIdaho sign-in for Canvas</td></tr><tr><td><strong>AI use</strong></td><td>🟢 AI on: asking a tool where a setting is · 🔴 AI off: the safety contract signature</td></tr><tr><td><strong>Cost</strong></td><td>$0. No step needs a payment method, and the safety contract asks you not to add one (<a href="./safety-contract.html#6-spending-caps-at-zero">rule 6</a>)</td></tr></tbody></table><p>This course assumes you know git, the command line, and Python or JavaScript. It doesn&#39;t assume you have used a coding agent seriously, run a local model or written an MCP server; those are the course. Terms that are new are in the <a href="./../resources/glossary.html">glossary</a>. Product limits and model names are in <a href="./../TOOLS.html">Tool Handout</a>, the only page that holds them.</p><p>Work through the steps in order. If one fails, keep going and bring the problem to the first Lab, or to office hours before it (<a href="#if-you-get-stuck">if you get stuck</a>).</p><h2 id="the-90-minutes" tabindex="-1">The 90 minutes <a class="header-anchor" href="#the-90-minutes" aria-label="Permalink to &quot;The 90 minutes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Do this</th><th>About</th></tr></thead><tbody><tr><td>1</td><td>GitHub account checked, two-factor authentication on, Student Developer Pack applied for</td><td>15 min</td></tr><tr><td>2</td><td>Data and privacy settings in Copilot and your chat assistant</td><td>10 min</td></tr><tr><td>3</td><td>One free LLM API key, stored safely, tested without printing it</td><td>20 min</td></tr><tr><td>4</td><td>A test Codespace with Node 22, Copilot answering in Ask mode</td><td>20 min</td></tr><tr><td>5</td><td>Reach the lab machine&#39;s local models (and, optionally, run Ollama on your laptop)</td><td>15 min</td></tr><tr><td>6</td><td>Read the agent safety contract and write down your questions</td><td>10 min</td></tr></tbody></table><h3 id="step-1--github-and-the-student-developer-pack-15-min" tabindex="-1">Step 1 — GitHub and the Student Developer Pack (15 min) <a class="header-anchor" href="#step-1--github-and-the-student-developer-pack-15-min" aria-label="Permalink to &quot;Step 1 — GitHub and the Student Developer Pack (15 min)&quot;">​</a></h3><p>Details: <a href="./accounts.html">Accounts</a>.</p><ol><li>Use a <strong>personal</strong> GitHub account you&#39;ll keep after graduating. If your only account is managed by an employer, make a separate one.</li><li>Turn on two-factor authentication (a passkey or an authenticator app) and save the recovery codes in a password manager.</li><li>Settings → <strong>Emails</strong> → tick <strong>Keep my email addresses private</strong> and <strong>Block command line pushes that expose my email</strong>. Your commits will be in public forks.</li><li>Apply for <strong>GitHub Education</strong> with your UIdaho email or student ID. It gives you Copilot Student and GitHub Pro&#39;s larger Codespaces and Actions allowances. Verification can take days, so do this first. While you wait, turn on Copilot Free.</li></ol><p>✅ <strong>Checkpoint:</strong> GitHub asks for your second factor on a new browser, and the Education application shows as submitted.</p><h3 id="step-2--data-settings-10-min" tabindex="-1">Step 2 — Data settings (10 min) <a class="header-anchor" href="#step-2--data-settings-10-min" aria-label="Permalink to &quot;Step 2 — Data settings (10 min)&quot;">​</a></h3><p>The course&#39;s <strong>data rule</strong> (<a href="./safety-contract.html#1-the-data-rule">contract rule 1</a>): free tiers may train on your prompts, so use them only on public open-source code and the course kits. Before you type anything:</p><ul><li><strong>Copilot:</strong> <a href="https://github.com/settings/copilot/features" target="_blank" rel="noreferrer">github.com/settings/copilot/features</a> → turn off use of your data for training. While you&#39;re there, set <strong>Suggestions matching public code</strong> to <strong>Block</strong>.</li><li><strong>Your chat assistant</strong> (Claude Free or ChatGPT Free, or Microsoft Copilot with your UIdaho sign-in): turn off the &quot;improve the model&quot; setting.</li><li><strong>Google AI Studio</strong> (step 3) has <strong>no opt-out on the free tier</strong>, and human reviewers may read prompts. That&#39;s why the data rule exists.</li></ul><p>Menus move. If a setting isn&#39;t where this page says, ask the tool where it is. More: <a href="./accounts.html#privacy-settings">Accounts: Privacy settings</a>.</p><p>✅ <strong>Checkpoint:</strong> for each tool, you can point to the setting you changed, or you know it has no opt-out.</p><h3 id="step-3--one-free-llm-api-key-20-min" tabindex="-1">Step 3 — One free LLM API key (20 min) <a class="header-anchor" href="#step-3--one-free-llm-api-key-20-min" aria-label="Permalink to &quot;Step 3 — One free LLM API key (20 min)&quot;">​</a></h3><p>Every course kit talks to a model through an OpenAI-compatible API configured by three environment variables: <code>LLM_BASE_URL</code>, <code>LLM_API_KEY</code> and <code>LLM_MODEL</code>. Get one key now; the primary provider and its base URL are in <a href="./../TOOLS.html#llm-apis-for-the-kits">Tool Handout: LLM APIs for the kits</a>.</p><ol><li>Sign in to Google AI Studio with a <strong>personal</strong> Google account (school accounts often have it switched off) and create an API key. Don&#39;t add billing.</li><li>Store the key in your password manager, not in a document or a chat.</li><li>Create a second key with the fallback provider in TOOLS.md, also with no payment method. You&#39;ll need it the first time the primary is rate-limited, which in this course is a matter of when.</li></ol><p>You&#39;ll test the key in step 4, inside a Codespace, so it never touches your laptop&#39;s shell history. How to handle keys from here on: <a href="./api-keys.html">API Keys, Tokens and Spending Caps</a>.</p><h3 id="step-4--a-test-codespace-20-min" tabindex="-1">Step 4 — A test Codespace (20 min) <a class="header-anchor" href="#step-4--a-test-codespace-20-min" aria-label="Permalink to &quot;Step 4 — A test Codespace (20 min)&quot;">​</a></h3><p>Every lab runs in a GitHub Codespace, and untrusted code always does (<a href="./safety-contract.html#3-untrusted-code-runs-in-a-sandbox">contract rule 3</a>). What a Codespace protects you from, and what it doesn&#39;t: <a href="./sandboxes.html">Sandboxes: Codespaces and Dev Containers</a>.</p><ol><li><p>Create a <strong>private</strong> repository called <code>eswa-practice</code> with a README.</p></li><li><p><strong>Code</strong> → <strong>Codespaces</strong> → <strong>Create codespace on main</strong>.</p></li><li><p>In the terminal, check the versions. The kits need Node 20.12 or later, and the testing weeks need Node 22 (TOOLS.md has the exact versions):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div></li><li><p>Add your key as a <strong>Codespaces secret</strong> for this repository only: github.com → Settings → Codespaces → <strong>New secret</strong>, name <code>LLM_API_KEY</code>, repository <code>eswa-practice</code>. Reload the codespace when VS Code offers. Then set the two non-secret variables for this terminal session, with the values from TOOLS.md:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LLM_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[base URL from TOOLS.md]&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LLM_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[model ID from TOOLS.md]&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$LLM_API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;LLM_API_KEY is set&quot;</span></span></code></pre></div></li><li><p>Send one request. The command strips any trailing slash from the base URL and never prints the key:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LLM_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">%/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/chat/completions&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$LLM_API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">model</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$LLM_MODEL</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">messages</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">: [{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">role</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">user</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">content</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Reply with the word ready.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}]}&quot;</span></span></code></pre></div></li><li><p>Open the Copilot chat in <strong>Ask</strong> mode and ask it what <code>\${LLM_BASE_URL%/}</code> does in bash. Check its answer against the bash manual&#39;s &quot;parameter expansion&quot; section: that&#39;s the course&#39;s verification habit in miniature.</p></li><li><p><strong>Stop the codespace</strong> (github.com/codespaces → … → Stop). Running codespaces use up your monthly hours.</p></li></ol><p>✅ <strong>Checkpoint:</strong> the response contains JSON with <code>&quot;choices&quot;</code> and the word <em>ready</em>; Copilot answered in the chat; the codespace is stopped. A <code>401</code> means the key is wrong; a <code>404</code> usually means the base URL or model ID is (<a href="./../resources/troubleshooting.html#my-api-call-fails-401-404-429">troubleshooting</a>).</p><h3 id="step-5--the-lab-machine-and-optionally-your-laptop-15-min" tabindex="-1">Step 5 — The lab machine, and optionally your laptop (15 min) <a class="header-anchor" href="#step-5--the-lab-machine-and-optionally-your-laptop-15-min" aria-label="Permalink to &quot;Step 5 — The lab machine, and optionally your laptop (15 min)&quot;">​</a></h3><p>The class has a lab machine that serves open-weight models through Ollama, one shared queue for everyone (<a href="./local-models.html#on-the-lab-machine">Local Models: Ollama on a Laptop and on the Lab Machine: On the lab machine</a>).</p><ol><li><strong>The lab machine.</strong> Your instructor&#39;s week 0 message gives its address and how to reach it (the campus network or VPN, or an authenticated endpoint that also works from a Codespace). Run the <a href="./local-models.html#the-tool-calling-smoke-test">tool-calling smoke test</a> against it with the lab model from TOOLS.md. If you haven&#39;t received the address yet, do this in the first Lab instead.</li><li><strong>(Optional) your laptop.</strong> If it has 16 GB of RAM or more, install Ollama, start it with the 64K context and run the same smoke test. It gives you an unlimited, private fallback for the kit labs. If your laptop is smaller, skip this: the lab machine and the free APIs cover you.</li></ol><p>✅ <strong>Checkpoint:</strong> the smoke test printed <code>TOOL CALL:</code> against the lab machine (or you know when you&#39;ll try it).</p><h3 id="step-6--read-the-agent-safety-contract-10-min" tabindex="-1">Step 6 — Read the agent safety contract (10 min) <a class="header-anchor" href="#step-6--read-the-agent-safety-contract-10-min" aria-label="Permalink to &quot;Step 6 — Read the agent safety contract (10 min)&quot;">​</a></h3><p>Read the <a href="./safety-contract.html">agent safety contract</a>. Its eleven rules exist because of real incidents, and you&#39;ll sign it on Canvas in week 1. Write down any rule you think is wrong or unclear and bring it to the first Seminar: disagreeing with a rule, with a reason, is a good start to this course.</p><p>✅ <strong>Checkpoint:</strong> you can say why an agent that reads a stranger&#39;s GitHub issue must not have your real keys within reach.</p><h2 id="youre-ready-for-the-first-seminar-when" tabindex="-1">You&#39;re ready for the first Seminar when <a class="header-anchor" href="#youre-ready-for-the-first-seminar-when" aria-label="Permalink to &quot;You&#39;re ready for the first Seminar when&quot;">​</a></h2><ul><li>☐ I can sign in to Canvas.</li><li>☐ My GitHub account has two-factor authentication and private email on, and my GitHub Education application is in.</li><li>☐ Copilot&#39;s training setting is off, and so is my chat assistant&#39;s.</li><li>☐ I have a primary and a fallback LLM API key, both with no payment method, stored in a password manager.</li><li>☐ My key worked from a Codespace without ever being printed, and the codespace is stopped.</li><li>☐ The tool-calling smoke test passed against the lab machine (or I know when I&#39;ll run it).</li><li>☐ I read the safety contract and wrote down my questions.</li><li>☐ I know where <a href="./../TOOLS.html">Tool Handout</a> and <a href="./../resources/troubleshooting.html">troubleshooting</a> are.</li></ul><h2 id="during-week-1" tabindex="-1">During week 1 <a class="header-anchor" href="#during-week-1" aria-label="Permalink to &quot;During week 1&quot;">​</a></h2><ul><li><strong>Sign the agent safety contract on Canvas</strong> (10 min). It is personal: don&#39;t commit it to a repository.</li><li><strong>GitHub Education.</strong> If it isn&#39;t approved by the end of week 1, tell your instructor. Copilot Free covers week 1; Copilot Student matters from week 2.</li><li><strong>Read <a href="./../weeks/01-agentic-engineering/">the week 1 page</a></strong> and its &quot;Before the Seminar&quot; row.</li></ul><h2 id="the-rest-of-this-folder" tabindex="-1">The rest of this folder <a class="header-anchor" href="#the-rest-of-this-folder" aria-label="Permalink to &quot;The rest of this folder&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Read it</th></tr></thead><tbody><tr><td><a href="./accounts.html">Accounts</a></td><td>Now: every account the course uses, when you need it, privacy settings</td></tr><tr><td><a href="./api-keys.html">API Keys, Tokens and Spending Caps</a></td><td>Before week 1&#39;s Lab: keys in <code>.env</code>, scoped tokens, spending caps, switching providers</td></tr><tr><td><a href="./sandboxes.html">Sandboxes: Codespaces and Dev Containers</a></td><td>Before week 2: Codespaces and dev containers for running agents on code you didn&#39;t write</td></tr><tr><td><a href="./local-models.html">Local Models: Ollama on a Laptop and on the Lab Machine</a></td><td>Before week 1&#39;s Lab if you&#39;ll use the lab machine or a laptop model</td></tr><tr><td><a href="./safety-contract.html">Agent Safety Contract</a></td><td>Now, then sign it in week 1</td></tr></tbody></table><h2 id="if-you-get-stuck" tabindex="-1">If you get stuck <a class="header-anchor" href="#if-you-get-stuck" aria-label="Permalink to &quot;If you get stuck&quot;">​</a></h2><ol><li>Check <a href="./../resources/troubleshooting.html">Troubleshooting</a>.</li><li>Ask the tool&#39;s own assistant where a setting is. Never paste a key, password or recovery code into it.</li><li>Email your instructor before the first Seminar with what you tried and the exact error. Account problems are far easier to fix before week 1 than during it.</li></ol>`,39)])])}const k=e(n,[["render",o]]);export{u as __pageData,k as default};
